CREATE TABLE "BusinessClient" ("id" TEXT NOT NULL,"company" TEXT NOT NULL,"contactName" TEXT,"address" TEXT,"vatTin" TEXT,"email" TEXT,"phone" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "BusinessClient_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CatalogueItem" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"description" TEXT NOT NULL,"unitPrice" DOUBLE PRECISION NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CatalogueItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Quotation" ("id" TEXT NOT NULL,"quotationNo" TEXT NOT NULL,"quotationDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"validDays" INTEGER NOT NULL DEFAULT 30,"projectRef" TEXT,"jobDescription" TEXT NOT NULL,"currency" TEXT NOT NULL DEFAULT 'USD',"vatRate" DOUBLE PRECISION NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'DRAFT',"revision" INTEGER NOT NULL DEFAULT 0,"clientId" TEXT NOT NULL,"projectId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"deletedAt" TIMESTAMP(3),CONSTRAINT "Quotation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "QuotationLine" ("id" TEXT NOT NULL,"position" INTEGER NOT NULL,"itemCode" TEXT NOT NULL,"description" TEXT NOT NULL,"quantity" DOUBLE PRECISION NOT NULL DEFAULT 1,"days" DOUBLE PRECISION NOT NULL DEFAULT 1,"unitPrice" DOUBLE PRECISION NOT NULL DEFAULT 0,"quotationId" TEXT NOT NULL,"catalogueItemId" TEXT,CONSTRAINT "QuotationLine_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CatalogueItem_code_key" ON "CatalogueItem"("code");
CREATE UNIQUE INDEX "Quotation_quotationNo_key" ON "Quotation"("quotationNo");
CREATE INDEX "QuotationLine_quotationId_position_idx" ON "QuotationLine"("quotationId", "position");
ALTER TABLE "Quotation" ADD CONSTRAINT "Quotation_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "BusinessClient"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Quotation" ADD CONSTRAINT "Quotation_projectId_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QuotationLine" ADD CONSTRAINT "QuotationLine_quotationId_fkey" FOREIGN KEY ("quotationId") REFERENCES "Quotation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "QuotationLine" ADD CONSTRAINT "QuotationLine_catalogueItemId_fkey" FOREIGN KEY ("catalogueItemId") REFERENCES "CatalogueItem"("id") ON DELETE SET NULL ON UPDATE CASCADE;